import{_ as d,C as e,c as i,o as n,a3 as s,G as t,w as l}from"./chunks/framework.Dk6sf0Ip.js";const v=JSON.parse('{"title":"Manual de Uso: OT Abierta Nuevamente - Mantenimiento de Unidades","description":"","frontmatter":{},"headers":[],"relativePath":"flows/Mantenimiento/abrirNuevamente.md","filePath":"flows/Mantenimiento/abrirNuevamente.md","lastUpdated":null}'),c={name:"flows/Mantenimiento/abrirNuevamente.md"};function u(m,a,h,p,g,b){const r=e("lite-youtube"),o=e("ClientOnly");return n(),i("div",null,[a[0]||(a[0]=s('<h1 id="manual-de-uso-ot-abierta-nuevamente-mantenimiento-de-unidades" tabindex="-1">Manual de Uso: OT Abierta Nuevamente - Mantenimiento de Unidades <a class="header-anchor" href="#manual-de-uso-ot-abierta-nuevamente-mantenimiento-de-unidades" aria-label="Permalink to &quot;Manual de Uso: OT Abierta Nuevamente - Mantenimiento de Unidades&quot;">​</a></h1><h2 id="_1-descripcion-general" tabindex="-1">1. Descripción General <a class="header-anchor" href="#_1-descripcion-general" aria-label="Permalink to &quot;1. Descripción General&quot;">​</a></h2><p>Esta pantalla permite registrar y gestionar una <strong>Orden de Trabajo (OT)</strong> que se vuelve a abrir para su seguimiento o modificación. Se pueden ingresar datos de la unidad, proveedor, solicitante, tareas a realizar y observaciones. Además, permite adjuntar archivos y acceder al módulo de compras si es necesario.</p><h2 id="_2-campos-y-funciones" tabindex="-1">2. Campos y Funciones <a class="header-anchor" href="#_2-campos-y-funciones" aria-label="Permalink to &quot;2. Campos y Funciones&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Campo / Botón</th><th>Descripción</th><th>Ejemplo / Acción</th></tr></thead><tbody><tr><td><strong>ID</strong></td><td>Número interno de la OT</td><td>10253</td></tr><tr><td><strong>Solicitud N°</strong></td><td>Número de solicitud relacionada</td><td>277</td></tr><tr><td><strong>Fecha de la OT</strong></td><td>Fecha de creación de la OT</td><td>10/04/2025</td></tr><tr><td><strong>Fecha Compromiso</strong></td><td>Fecha límite para completar la OT</td><td>10/04/2025</td></tr><tr><td><strong>Referencia</strong></td><td>Descripción corta de la tarea</td><td>6 DESARME Y ARME</td></tr><tr><td><strong>Patente</strong></td><td>Matrícula de la unidad</td><td>PBG295</td></tr><tr><td><strong>Proveedor</strong></td><td>Nombre del proveedor asignado a la OT.</td><td>ALBERTO ADRIAN AYALA</td></tr><tr><td><strong>Solicitante</strong></td><td>Persona que solicita la OT</td><td>Flows Manager</td></tr><tr><td><strong>Responsable</strong></td><td>Persona encargada de ejecutar la OT</td><td>CUELLO CRISTIAN ROQUE</td></tr><tr><td><strong>Tarea a realizar</strong></td><td>Descripción detallada del trabajo</td><td>6 DESARME Y ARME</td></tr><tr><td><strong>Obs Actuar</strong></td><td>Observaciones adicionales o instrucciones</td><td>6 DESARME Y ARME</td></tr><tr><td><strong>Km</strong></td><td>Kilometraje de la unidad</td><td>0</td></tr><tr><td><strong>Hs</strong></td><td>Horas de trabajo registradas</td><td>0</td></tr><tr><td><strong>COMPRAS</strong></td><td>Accede al módulo de compras para solicitar materiales o insumos necesarios</td><td>Botón</td></tr><tr><td><strong>SELECCIONAR ARCHIVO PARA ADJUNTAR</strong></td><td>Permite subir documentos o imágenes relacionados a la OT</td><td>Link para adjuntar archivo</td></tr><tr><td><strong>CERRAR</strong></td><td>Cierra la ventana sin guardar cambios</td><td>Botón</td></tr><tr><td><strong>GUARDAR</strong></td><td>Guarda los cambios realizados en la OT</td><td>Botón</td></tr><tr><td><strong>SIGUIENTE</strong></td><td>Avanza a la siguiente OT abierta o siguiente paso</td><td>Botón</td></tr></tbody></table><h2 id="_3-procedimiento-paso-a-paso" tabindex="-1">3. Procedimiento Paso a Paso <a class="header-anchor" href="#_3-procedimiento-paso-a-paso" aria-label="Permalink to &quot;3. Procedimiento Paso a Paso&quot;">​</a></h2><h3 id="_1-abrir-la-ot" tabindex="-1">1. Abrir la OT <a class="header-anchor" href="#_1-abrir-la-ot" aria-label="Permalink to &quot;1. Abrir la OT&quot;">​</a></h3><ul><li>Accede a la lista de OT abiertas y selecciona la OT que deseas modificar o revisar.</li></ul><h3 id="_2-verificar-los-datos-de-la-ot" tabindex="-1">2. Verificar los datos de la OT <a class="header-anchor" href="#_2-verificar-los-datos-de-la-ot" aria-label="Permalink to &quot;2. Verificar los datos de la OT&quot;">​</a></h3><ul><li>Revisa los campos de <code>Solicitud N°</code>, <code>Fecha</code>, <code>Referencia</code> y <code>Patente</code> para asegurarte que corresponde a la unidad correcta.</li></ul><h3 id="_3-asignar-proveedor-y-responsable" tabindex="-1">3. Asignar proveedor y responsable <a class="header-anchor" href="#_3-asignar-proveedor-y-responsable" aria-label="Permalink to &quot;3. Asignar proveedor y responsable&quot;">​</a></h3><ul><li>Si es necesario, modifica el <code>Proveedor</code> usando los iconos de búsqueda o agregar nuevo.</li><li>Selecciona el <code>Responsable</code> encargado de ejecutar la OT.</li></ul><h3 id="_4-completar-informacion-de-la-tarea" tabindex="-1">4. Completar información de la tarea <a class="header-anchor" href="#_4-completar-informacion-de-la-tarea" aria-label="Permalink to &quot;4. Completar información de la tarea&quot;">​</a></h3><ul><li>Ingresa la descripción de la <code>Tarea a realizar</code> y cualquier observación adicional en <code>Obs Actuar</code>.</li><li>Si corresponde, registra <code>Km</code> y <code>Hs</code> trabajadas.</li></ul><h3 id="_5-adjuntar-archivos" tabindex="-1">5. Adjuntar archivos <a class="header-anchor" href="#_5-adjuntar-archivos" aria-label="Permalink to &quot;5. Adjuntar archivos&quot;">​</a></h3><ul><li>Haz clic en <strong>Seleccionar archivo para adjuntar</strong> y sube cualquier documento o imagen relevante.</li></ul><h3 id="_6-acceso-a-compras" tabindex="-1">6. Acceso a compras <a class="header-anchor" href="#_6-acceso-a-compras" aria-label="Permalink to &quot;6. Acceso a compras&quot;">​</a></h3><ul><li>Si se requieren materiales o repuestos, haz clic en <strong>COMPRAS</strong> para abrir el módulo de compras.</li></ul><h3 id="_7-guardar-cambios" tabindex="-1">7. Guardar cambios <a class="header-anchor" href="#_7-guardar-cambios" aria-label="Permalink to &quot;7. Guardar cambios&quot;">​</a></h3><ul><li>Haz clic en <strong>GUARDAR</strong> para registrar todas las modificaciones.</li></ul><h3 id="_8-cerrar-o-avanzar" tabindex="-1">8. Cerrar o avanzar <a class="header-anchor" href="#_8-cerrar-o-avanzar" aria-label="Permalink to &quot;8. Cerrar o avanzar&quot;">​</a></h3><ul><li>Para salir sin guardar, haz clic en <strong>CERRAR</strong>.</li><li>Para continuar con la siguiente OT o paso, haz clic en <strong>SIGUIENTE</strong>.</li></ul><h2 id="_4-notas-importantes" tabindex="-1">4. Notas Importantes <a class="header-anchor" href="#_4-notas-importantes" aria-label="Permalink to &quot;4. Notas Importantes&quot;">​</a></h2><ul><li>Asegúrate de completar todos los campos obligatorios antes de guardar.</li><li>La fecha de compromiso debe ser coherente con la disponibilidad de recursos y materiales.</li><li>Archivos adjuntos pueden incluir fotos del equipo, documentos de seguridad o checklists.</li></ul><h2 id="_5-video-tutorial" tabindex="-1">5. Video tutorial <a class="header-anchor" href="#_5-video-tutorial" aria-label="Permalink to &quot;5. Video tutorial&quot;">​</a></h2>',25)),t(o,null,{default:l(()=>[t(r,{videoid:"IIYKgRLjmvY",videotitle:"Flujo de carga de mantenimientos - 20.2.02 OT Abierta nuevamente"})]),_:1})])}const A=d(c,[["render",u]]);export{v as __pageData,A as default};
